Definition qcpsat_fill_ints_entail_wit_2_split_goal_1 :=
forall (n_pre: Z) (value_pre: Z) (i: Z) (PreH1 : (i < n_pre)) (PreH2 : (0 <= i)) (PreH3 : (i <= n_pre)) (PreH4 : (0 <= n_pre)) (PreH5 : (n_pre < INT_MAX)),
