Definition qcpsat_fill_ints_return_wit_1 :=
(
forall (a_pre: Z) (n_pre: Z) (value_pre: Z) (i: Z) (PreH1 : (i >= n_pre)) (PreH2 : (0 <= i)) (PreH3 : (i <= n_pre)) (PreH4 : (0 <= n_pre)) (PreH5 : (n_pre < INT_MAX)),
  (IntArray.full a_pre i (repeat_Z (value_pre) (i)) )
  **  (IntArray.undef_seg a_pre i n_pre )
|--
  (IntArray.full a_pre n_pre (repeat_Z (value_pre) (n_pre)) )
) \/
(
forall (a_pre: Z) (n_pre: Z) (value_pre: Z) (i: Z) (PreH1 : (i >= n_pre)) (PreH2 : (0 <= i)) (PreH3 : (i <= n_pre)) (PreH4 : (0 <= n_pre)) (PreH5 : (n_pre < INT_MAX)),
  (IntArray.full a_pre i (repeat_Z (value_pre) (i)) )
|--
  (IntArray.full a_pre n_pre (repeat_Z (value_pre) (n_pre)) )
).

